--
-- Estructura para la vista `v_unified_products`
--
DROP TABLE IF EXISTS `v_unified_products`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_unified_products`  AS SELECT concat('internal:',`p`.`id`) AS `item_key`, 'internal' AS `source_type`, `p`.`id` AS `source_id`, 'Devioz' AS `source_name`, `p`.`name` AS `name`, '' AS `brand`, `p`.`code` AS `code`, `p`.`category` AS `category`, if(`p`.`units_per_pack` > 1,concat(`p`.`units_per_pack`,' unidades'),'Unidad') AS `presentation`, `p`.`cost_price` AS `cost`, `p`.`price` AS `sale_price`, `p`.`stock` AS `stock`, `p`.`active` AS `available`, `p`.`image_url` AS `image_url`, `p`.`updated_at` AS `updated_at`, 'real' AS `profit_type` FROM `products` AS `p`union all select concat('external:',`e`.`id_producto`) AS `CONCAT('external:',e.id_producto)`,'external' AS `source_type`,`e`.`id_producto` AS `id_producto`,coalesce(`s`.`nombre`,nullif(`e`.`supermercado`,''),'Proveedor') AS `COALESCE(s.nombre,NULLIF(e.supermercado,''),'Proveedor')`,`e`.`producto` AS `producto`,coalesce(`e`.`marca`,'') AS `COALESCE(e.marca,'')`,coalesce(nullif(`e`.`ean`,''),concat('EXT-',`e`.`id_producto`)) AS `COALESCE(NULLIF(e.ean,''),CONCAT('EXT-',e.id_producto))`,coalesce(`e`.`categoria`,'Sin categoría') AS `COALESCE(e.categoria,'Sin categoría')`,coalesce(nullif(`e`.`presentacion`,''),nullif(`e`.`unidad`,''),'Unidad') AS `COALESCE(NULLIF(e.presentacion,''),NULLIF(e.unidad,''),'Unidad')`,`e`.`precio_actual` AS `precio_actual`,case when `e`.`precio_actual` is null or `e`.`precio_actual` <= 0 then NULL else coalesce(`ep`.`custom_sale_price`,round(`e`.`precio_actual` * (1 + coalesce(`ep`.`custom_margin_pct`,cast(`cfg`.`setting_value` as decimal(7,2)),25) / 100),2)) end AS `Name_exp_11`,NULL AS `NULL`,case when `e`.`activo` = 1 and ucase(coalesce(`e`.`estado_disponibilidad`,'DISPONIBLE')) not in ('NO DISPONIBLE','AGOTADO','SIN STOCK') then 1 else 0 end AS `Name_exp_13`,`e`.`imagen` AS `imagen`,coalesce(`e`.`fecha_extraccion`,`e`.`fecha_carga`) AS `COALESCE(e.fecha_extraccion,e.fecha_carga)`,'estimated' AS `estimated` from (((`productos` `e` left join `supermercados` `s` on(`s`.`id_supermercado` = `e`.`id_supermercado`)) left join `external_product_pricing` `ep` on(`ep`.`external_product_id` = `e`.`id_producto`)) left join `store_settings` `cfg` on(`cfg`.`setting_key` = 'external_default_margin_pct'))  ;

